// Every row in one request: the API's import is a single call that
// creates what is new, recognises what is already known (by number),
// rejects what is unusable, and adds them all to the campaign.
const rows = $input.all().map((item) => item.json);
const config = $('Config').first().json;
return [{
  json: {
    rows,
    campaign: config.campaignName,
    create_campaign: true,
    dry_run: false,
  },
}];

const imported = $('POST /prospects/import').first().json;
const campaign = $json.campaign;
return [{
  json: {
    campaign: campaign.name,
    status: campaign.status,
    created: imported.created,
    already_known: imported.duplicates,
    rejected: imported.rejected_count,
    rejected_rows: imported.rejected,
    members: campaign.counts ? campaign.counts.total : null,
    note: 'The scheduler (uv run campaign.py run) places the calls.',
  },
}];
